// The data behind /quality, generated by evals/publish_quality.py. The page is static, so a
// missing field throws during `next build` and the deploy stops (docs/08-transparency.md, 8).

export type Stat = { mean: number; low: number; high: number; n: number };

export type Score = Stat & {
  group: "all" | "he" | "en" | "cross_lingual";
  metric: "recall@5" | "mrr";
  threshold: number | null;
  passed: boolean | null;
};

export type MethodRow = {
  method: string;
  all: Stat;
  he: Stat;
  en: Stat;
  cross_lingual: Stat;
  mrr: Stat;
};

export type Experiment = {
  date: string;
  commit: string;
  questions: number;
  chosen: string;
  rows: MethodRow[];
};

export type Quality = {
  schema: 1;
  official: null;
  latest: { date: string; commit: string; split: string; questions: number; chunks: number };
  scorecard: Score[];
  hybrid: Experiment;
  rerank: Experiment & {
    difference: Record<"all" | "he" | "en" | "cross_lingual", Stat>;
    improved: number;
    worsened: number;
    still_missing: number;
  };
};

function need(condition: boolean, what: string): asserts condition {
  if (!condition) throw new Error(`quality.json: ${what}`);
}

function checkStat(value: unknown, where: string) {
  const s = value as Partial<Stat> | undefined;
  for (const key of ["mean", "low", "high", "n"] as const) {
    need(typeof s?.[key] === "number", `${where}.${key} is missing`);
  }
}

function checkExperiment(value: unknown, where: string) {
  const e = value as Partial<Experiment> | undefined;
  need(typeof e?.date === "string" && typeof e?.commit === "string", `${where} has no date or commit`);
  need(typeof e?.questions === "number", `${where}.questions is missing`);
  need(Array.isArray(e?.rows) && e.rows.length > 0, `${where}.rows is empty`);
  need(e.rows.some((r) => r.method === e.chosen), `${where}.chosen is not one of the rows`);
  e.rows.forEach((r, i) => {
    for (const key of ["all", "he", "en", "cross_lingual", "mrr"] as const) {
      checkStat(r[key], `${where}.rows[${i}].${key}`);
    }
  });
}

export function parseQuality(data: unknown): Quality {
  const q = data as Partial<Quality> | null;
  need(q?.schema === 1, "unknown schema");
  need(q.official === null, "official results need a page section first");
  need(typeof q.latest?.date === "string" && typeof q.latest?.commit === "string", "latest is incomplete");
  need(typeof q.latest.questions === "number" && typeof q.latest.chunks === "number", "latest is incomplete");
  need(Array.isArray(q.scorecard) && q.scorecard.length > 0, "scorecard is empty");
  q.scorecard.forEach((row, i) => checkStat(row, `scorecard[${i}]`));
  checkExperiment(q.hybrid, "hybrid");
  checkExperiment(q.rerank, "rerank");
  for (const group of ["all", "he", "en", "cross_lingual"] as const) {
    checkStat(q.rerank?.difference?.[group], `rerank.difference.${group}`);
  }
  for (const key of ["improved", "worsened", "still_missing"] as const) {
    need(typeof q.rerank?.[key] === "number", `rerank.${key} is missing`);
  }
  return q as Quality;
}

export const num = (value: number) => value.toFixed(2);

export const signed = (value: number) => `${value >= 0 ? "+" : "−"}${Math.abs(value).toFixed(2)}`;

export const interval = (s: Pick<Stat, "low" | "high">) => `[${num(s.low)}, ${num(s.high)}]`;

// The lower bound has three decimals: +0.005 would round to a misleading +0.00 or +0.01.
export const signedFine = (value: number) => `${value >= 0 ? "+" : "−"}${Math.abs(value).toFixed(3)}`;
